// ── source: vcx/platform/store_grpc_call_auth_test.v ──
// store_grpc_call_auth_test.v — the gRPC edge's per-call XSP-AUTH (RULED G1a
// 2026-08-08; cxstore-grpc.md §4). The bearer plane is retired: a call carries
// a CxCall credential (a DID's ed25519 signature binding the method path + body
// + timestamp + nonce), verified by the same authority path the profile uses.
// These pins are the live consumer of that gate.

const cauth_path = '/cxstore.v1.CxStore/Put'

fn cauth_identity(tag u8) (string, []u8) {
	mut seed := []u8{len: 32}
	for i in 0 .. 32 {
		seed[i] = u8((i * 5 + int(tag)) & 0xff)
	}
	did := did_key_from_seed(seed) or { panic('did: ${err}') }
	return did, seed
}

fn cauth_body() []u8 {
	return '[doc [n 1]]'.bytes()
}

// a well-formed credential verifies and yields a session bound to the DID.
fn test_call_auth_verifies_and_binds_principal() {
	did, seed := cauth_identity(1)
	body := cauth_body()
	header := grpc_call_auth_header(did, seed, cauth_path, body, '') or { panic('header') }
	mut nc := new_grpc_nonce_cache()
	c := grpc_call_auth_verify(header, cauth_path, body, XspConfig{}, map[string]bool{},
		'docs', mut nc) or {
		panic('verify must succeed: ${err}')
	}
	assert c.principal == did, 'session principal must be the signing DID'
	assert c.mutual, 'a signed call is a mutual (DID-proven) session'
}

// a body that differs from the one the credential signed is refused (the
// signature binds the exact bytes).
fn test_call_auth_body_binding_refused() {
	did, seed := cauth_identity(2)
	header := grpc_call_auth_header(did, seed, cauth_path, cauth_body(), '') or { panic('header') }
	mut nc := new_grpc_nonce_cache()
	if _ := grpc_call_auth_verify(header, cauth_path, '[doc [n 999]]'.bytes(), XspConfig{},
		map[string]bool{}, 'docs', mut nc)
	{
		assert false, 'a mismatched body must be REFUSED'
	}
}

// a path that differs from the one the credential signed is refused (the
// signature binds the exact method).
fn test_call_auth_path_binding_refused() {
	did, seed := cauth_identity(3)
	body := cauth_body()
	header := grpc_call_auth_header(did, seed, cauth_path, body, '') or { panic('header') }
	mut nc := new_grpc_nonce_cache()
	if _ := grpc_call_auth_verify(header, '/cxstore.v1.CxStore/Delete', body, XspConfig{},
		map[string]bool{}, 'docs', mut nc)
	{
		assert false, 'a mismatched method path must be REFUSED'
	}
}

// the nonce cache refuses a replay inside the freshness window.
fn test_call_auth_replay_refused() {
	did, seed := cauth_identity(4)
	body := cauth_body()
	header := grpc_call_auth_header(did, seed, cauth_path, body, '') or { panic('header') }
	mut nc := new_grpc_nonce_cache()
	grpc_call_auth_verify(header, cauth_path, body, XspConfig{}, map[string]bool{}, 'docs', mut
		nc) or {
		panic('first use must verify: ${err}')
	}
	if _ := grpc_call_auth_verify(header, cauth_path, body, XspConfig{}, map[string]bool{},
		'docs', mut nc)
	{
		assert false, 'a replayed credential must be REFUSED'
	}
}

// a signature by a key that does not match the claimed DID is refused.
fn test_call_auth_wrong_signer_refused() {
	did, _ := cauth_identity(5)
	_, other_seed := cauth_identity(6)
	body := cauth_body()
	// sign with other_seed but claim `did` (mismatch)
	header := grpc_call_auth_header(did, other_seed, cauth_path, body, '') or { panic('header') }
	mut nc := new_grpc_nonce_cache()
	if _ := grpc_call_auth_verify(header, cauth_path, body, XspConfig{}, map[string]bool{},
		'docs', mut nc)
	{
		assert false, 'a signature not matching the claimed DID must be REFUSED'
	}
}

// a non-CxCall authorization (e.g. the retired Bearer form) is refused.
fn test_call_auth_bearer_refused() {
	body := cauth_body()
	mut nc := new_grpc_nonce_cache()
	if _ := grpc_call_auth_verify('Bearer some-token', cauth_path, body, XspConfig{},
		map[string]bool{}, 'docs', mut nc)
	{
		assert false, 'a retired Bearer credential must be REFUSED'
	}
}

// deny-by-default posture (grants configured): a call with NO credential is
// UNAUTHENTICATED; a valid credential for a granted DID PERMITS a data op.
fn test_call_gate_deny_by_default_posture() {
	did, seed := cauth_identity(7)
	cfg := XspConfig{
		grants: [XspGrant{
			did:  did
			caps: ['read', 'write']
		}]
	}
	ctx := ServeContext{
		xsp_cfg: cfg
	}
	mut nc := new_grpc_nonce_cache()
	body := cauth_body()
	// no credential → UNAUTHENTICATED
	if r := grpc_call_gate('', cauth_path, body, 'put', 'docs', ctx, mut nc) {
		assert r.status.code == grpc_unauthenticated, 'no-credential in deny posture → UNAUTHENTICATED, got ${r.status.code}'
	} else {
		assert false, 'a missing credential in the deny posture must be refused'
	}
	// valid credential for a granted DID → permitted (gate returns none)
	header := grpc_call_auth_header(did, seed, cauth_path, body, '') or { panic('header') }
	if r := grpc_call_gate(header, cauth_path, body, 'put', 'docs', ctx, mut nc) {
		assert false, 'a granted write must PERMIT, got refusal ${r.status.code}: ${r.status.message}'
	}
}

// open posture (no grants): a data op is permitted with no credential; an
// admin op requires a DID-proven credential (the mutual gate).
fn test_call_gate_open_posture() {
	ctx := ServeContext{} // no grants
	mut nc := new_grpc_nonce_cache()
	body := cauth_body()
	// data op, no credential → permitted
	if _ := grpc_call_gate('', cauth_path, body, 'put', 'docs', ctx, mut nc) {
		assert false, 'open posture must permit an anonymous data op'
	}
	// admin op, no credential → denied (mutual gate)
	apath := '/cxstore.v1.CxStore/Mounts'
	if r := grpc_call_gate('', apath, []u8{}, 'mounts', '', ctx, mut nc) {
		assert r.status.code == grpc_unauthenticated, 'open-posture admin needs a credential, got ${r.status.code}'
	} else {
		assert false, 'open-posture admin with no credential must be refused'
	}
	// admin op WITH a valid credential → permitted
	did, seed := cauth_identity(8)
	ah := grpc_call_auth_header(did, seed, apath, []u8{}, '') or { panic('header') }
	if r := grpc_call_gate(ah, apath, []u8{}, 'mounts', '', ctx, mut nc) {
		assert false, 'a DID-proven admin call must PERMIT, got ${r.status.code}: ${r.status.message}'
	}
}

// sanity: the header helper and did derivation agree on the key.
fn test_did_key_roundtrips_seed() {
	_, seed := cauth_identity(9)
	did := did_key_from_seed(seed) or { panic('did') }
	priv := ed25519.new_key_from_seed(seed)
	pub_from_did := did_key_bytes(did) or { panic('did_key_bytes') }
	assert pub_from_did == []u8(priv.public_key()), 'did:key must resolve back to the seed public key'
}

// ── source: vcx/platform/store_grpc_conn_test.v ──
// store_grpc_conn_test.v — HTTP/2 connection/stream reassembly (brick 3c). A
// hand-built client byte stream (preface + SETTINGS + HEADERS + DATA) is fed to
// H2Conn; we assert the server preface (SETTINGS + ACK) is emitted and one
// GrpcCall is reassembled with the right :path / content-type / message — fed
// both as one chunk and split across frame boundaries.

fn grpc_req_headers_block() []u8 {
	return hpack_encode_header_list([
		HpackHeader{':method', 'POST'},
		HpackHeader{':scheme', 'http'},
		HpackHeader{':path', '/cxstore.v1.CxStore/Put'},
		HpackHeader{'content-type', 'application/grpc'},
		HpackHeader{'te', 'trailers'},
	])
}

// build a full client request byte stream on stream 1 carrying `msg`.
fn grpc_client_stream(msg []u8) []u8 {
	mut b := []u8{}
	b << h2_preface.bytes()
	b << h2_frame_encode(h2_settings_frame([]H2Setting{}))
	b << h2_frame_encode(H2Frame{
		typ:       h2_headers
		flags:     h2_flag_end_headers
		stream_id: 1
		payload:   grpc_req_headers_block()
	})
	b << h2_frame_encode(H2Frame{
		typ:       h2_data
		flags:     h2_flag_end_stream
		stream_id: 1
		payload:   grpc_frame_encode(msg)
	})
	return b
}

// summarize the server's written frames: was a non-ACK SETTINGS sent, and an ACK?
fn server_emitted_settings_and_ack(out []u8) (bool, bool) {
	mut r := H2FrameReader{}
	r.feed(out)
	mut settings := false
	mut ack := false
	for {
		f := r.next() or { break }
		if f.typ == h2_settings {
			if f.has_flag(h2_flag_ack) {
				ack = true
			} else {
				settings = true
			}
		}
	}
	return settings, ack
}

fn assert_one_put_call(mut c H2Conn, msg []u8) {
	calls := c.take_calls()
	assert calls.len == 1, 'expected exactly one GrpcCall, got ${calls.len}'
	call := calls[0]
	assert call.stream_id == 1, 'stream id ${call.stream_id}'
	assert call.headers[':path'] == '/cxstore.v1.CxStore/Put', 'path: ${call.headers[':path']}'
	assert call.headers['content-type'] == 'application/grpc', 'content-type: ${call.headers['content-type']}'
	assert call.headers[':method'] == 'POST'
	assert call.message == msg, 'message bytes mismatch: ${call.message} vs ${msg}'
}

fn test_h2conn_single_chunk() {
	msg := [u8(0x0a), 0x03, `a`, `b`, `c`] // arbitrary proto-ish bytes
	mut c := new_h2_conn()
	out := c.feed(grpc_client_stream(msg))
	settings, ack := server_emitted_settings_and_ack(out)
	assert settings, 'server must emit its SETTINGS'
	assert ack, 'server must ACK the client SETTINGS'
	assert_one_put_call(mut c, msg)
}

fn test_h2conn_split_chunks() {
	msg := [u8(1), 2, 3, 4, 5, 6, 7]
	stream := grpc_client_stream(msg)
	mut c := new_h2_conn()
	// feed in three arbitrary slices straddling preface + frame boundaries
	a := stream.len / 3
	b := (stream.len * 2) / 3
	mut out := []u8{}
	out << c.feed(stream[..a])
	out << c.feed(stream[a..b])
	out << c.feed(stream[b..])
	settings, ack := server_emitted_settings_and_ack(out)
	assert settings, 'server SETTINGS across chunked feed'
	assert ack, 'server SETTINGS ACK across chunked feed'
	assert_one_put_call(mut c, msg)
}

fn test_h2conn_ping_ack() {
	mut c := new_h2_conn()
	mut b := []u8{}
	b << h2_preface.bytes()
	b << h2_frame_encode(h2_settings_frame([]H2Setting{}))
	b << h2_frame_encode(H2Frame{
		typ:     h2_ping
		payload: '12345678'.bytes()
	})
	out := c.feed(b)
	mut r := H2FrameReader{}
	r.feed(out)
	mut got_ping_ack := false
	for {
		f := r.next() or { break }
		if f.typ == h2_ping && f.has_flag(h2_flag_ack) && f.payload.bytestr() == '12345678' {
			got_ping_ack = true
		}
	}
	assert got_ping_ack, 'server must answer PING with PING-ACK echoing the payload'
}

// ── source: vcx/platform/store_grpc_e2e_test.v ──
// store_grpc_e2e_test.v — full gRPC server path, in memory + socket-free
// (brick 4b core): a client byte stream (preface+SETTINGS+HEADERS+DATA) → H2Conn
// reassembly → grpc_dispatch (real store pipeline) → grpc_encode_response →
// decoded back with a *client-side* HPACK decoder. Proves request decode,
// dispatch, response framing, and the trailer status are all wire-correct,
// without the socket plumbing (that glue is brick 4b-ii).

fn e2e_ctx() (&ServiceState, ServeContext) {
	mut s := new_service_state()
	s.mark_ready()
	ctx := ServeContext{
		mounts: {
			'docs': store_open_impl('mem://grpc-e2e', '', '', false, true, map[string]string{})
		}
	}
	return s, ctx
}

// build a client request byte stream for one unary call on stream 1.
fn e2e_client_stream(method string, msg []u8) []u8 {
	mut b := []u8{}
	b << h2_preface.bytes()
	b << h2_frame_encode(h2_settings_frame([]H2Setting{}))
	b << h2_frame_encode(H2Frame{
		typ:       h2_headers
		flags:     h2_flag_end_headers
		stream_id: 1
		payload:   hpack_encode_header_list([
			HpackHeader{':method', 'POST'},
			HpackHeader{':scheme', 'http'},
			HpackHeader{':path', '/cxstore.v1.CxStore/${method}'},
			HpackHeader{'content-type', 'application/grpc'},
			HpackHeader{'te', 'trailers'},
		])
	})
	b << h2_frame_encode(H2Frame{
		typ:       h2_data
		flags:     h2_flag_end_stream
		stream_id: 1
		payload:   grpc_frame_encode(msg)
	})
	return b
}

// run one full call against an H2Conn-backed server; return the decoded response
// (status pseudo-header, the first DATA message, the grpc-status trailer).
struct E2EResponse {
	http_status string
	message     []u8
	grpc_status string
}

fn e2e_call(mut c H2Conn, mut s ServiceState, ctx ServeContext, method string, msg []u8) E2EResponse {
	c.feed(e2e_client_stream(method, msg)) // server preface bytes ignored here
	mut wire := []u8{}
	for call in c.take_calls() {
		reply := grpc_dispatch(call, mut s, ctx)
		wire << grpc_encode_response(call.stream_id, reply)
	}
	// client-side decode of the server's frames
	mut r := H2FrameReader{}
	r.feed(wire)
	mut cli_dec := new_hpack_decoder(4096)
	mut http_status := ''
	mut grpc_status := ''
	mut message := []u8{}
	for {
		f := r.next() or { break }
		match f.typ {
			h2_headers {
				hdrs := cli_dec.decode(f.payload) or { []HpackHeader{} }
				for h in hdrs {
					if h.name == ':status' {
						http_status = h.value
					}
					if h.name == 'grpc-status' {
						grpc_status = h.value
					}
				}
			}
			h2_data {
				mut fr := GrpcFrameReader{}
				fr.feed(f.payload)
				if gf := fr.next() {
					message = gf.data.clone()
				}
			}
			else {}
		}
	}
	return E2EResponse{http_status, message, grpc_status}
}

fn test_grpc_e2e_put_then_get() {
	mut s, ctx := e2e_ctx()

	// PUT over the full wire path
	mut put_conn := new_h2_conn()
	put_resp := e2e_call(mut put_conn, mut s, ctx, 'Put', pb_encode_put_request(GrpcPutRequest{
		store:    'docs'
		body:     '[note [body "grpc-e2e"]]'.bytes()
		encoding: 'cxd'
	}))
	assert put_resp.http_status == '200', 'put :status ${put_resp.http_status}'
	assert put_resp.grpc_status == '0', 'put grpc-status ${put_resp.grpc_status}'
	pr := pb_decode_put_response(put_resp.message) or { panic('decode put') }
	assert pr.hash.starts_with('sha2-256:') && pr.hash.len == 73, 'put hash ${pr.hash}'

	// GET it back over the full wire path (new connection)
	mut get_conn := new_h2_conn()
	get_resp := e2e_call(mut get_conn, mut s, ctx, 'Get', pb_encode_get_request(GrpcGetRequest{
		store: 'docs'
		hash:  pr.hash
	}))
	assert get_resp.http_status == '200'
	assert get_resp.grpc_status == '0'
	gr := pb_decode_get_response(get_resp.message) or { panic('decode get') }
	assert gr.body.bytestr().contains('grpc-e2e'), 'doc round-trip over gRPC wire: ${gr.body.bytestr()}'
}

fn test_grpc_e2e_missing_hash_trailer_status() {
	mut s, ctx := e2e_ctx()
	mut conn := new_h2_conn()
	resp := e2e_call(mut conn, mut s, ctx, 'Get', pb_encode_get_request(GrpcGetRequest{
		store: 'docs'
		hash:  'sha2-256:' + '0'.repeat(64)
	}))
	// HTTP/2 is still 200 (gRPC errors ride the trailer, not the HTTP status).
	assert resp.http_status == '200'
	assert resp.grpc_status == grpc_not_found.str(), 'missing hash trailer grpc-status ${resp.grpc_status}, want ${grpc_not_found}'
}

// ── source: vcx/platform/store_grpc_frame_test.v ──
// store_grpc_frame_test.v — gRPC framing reassembly + status mapping (#105 2b
// brick 2). Pure, deterministic — no transport.

fn test_frame_roundtrip_single() {
	msg := '[note [body "hi"]]'.bytes()
	mut r := GrpcFrameReader{}
	r.feed(grpc_frame_encode(msg))
	f := r.next() or { panic('expected one frame') }
	assert !f.compressed
	assert f.data == msg
	if _ := r.next() {
		assert false, 'no second frame expected'
	}
}

fn test_frame_empty_message() {
	mut r := GrpcFrameReader{}
	r.feed(grpc_frame_encode([]u8{}))
	f := r.next() or { panic('empty frame should still decode') }
	assert f.data.len == 0
}

fn test_frame_multi_message_in_one_buffer() {
	mut buf := []u8{}
	buf << grpc_frame_encode('a'.bytes())
	buf << grpc_frame_encode('bb'.bytes())
	buf << grpc_frame_encode('ccc'.bytes())
	mut r := GrpcFrameReader{}
	r.feed(buf)
	mut got := []string{}
	for {
		f := r.next() or { break }
		got << f.data.bytestr()
	}
	assert got == ['a', 'bb', 'ccc'], '${got}'
}

fn test_frame_partial_then_completed() {
	full := grpc_frame_encode('hello-world'.bytes())
	mut r := GrpcFrameReader{}
	// feed only the first 3 bytes (less than the 5-byte header) → incomplete
	r.feed(full[..3])
	if _ := r.next() {
		assert false, 'must not yield from a partial header'
	}
	// feed the header remainder + half the body → still incomplete
	r.feed(full[3..8])
	if _ := r.next() {
		assert false, 'must not yield from a partial body'
	}
	// feed the rest → now a complete frame
	r.feed(full[8..])
	f := r.next() or { panic('frame should complete') }
	assert f.data.bytestr() == 'hello-world'
	assert r.pending() == 0
}

fn test_compressed_flag_surfaced() {
	// a frame with compression flag 1 must be reported as compressed (the
	// dispatcher rejects it — identity only — rather than mis-decode).
	mut framed := grpc_frame_encode('x'.bytes())
	framed[0] = 1
	mut r := GrpcFrameReader{}
	r.feed(framed)
	f := r.next() or { panic('frame') }
	assert f.compressed
}

fn test_status_for_cxer_full_table() {
	cases := {
		'cx-err:CXER1701': grpc_invalid_argument
		'cx-err:CXER1702': grpc_unauthenticated
		'cx-err:CXER1703': grpc_permission_denied
		'cx-err:CXER1114': grpc_aborted
		'cx-err:CXER1705': grpc_resource_exhausted
		'cx-err:CXER1706': grpc_resource_exhausted
		'cx-err:CXER1707': grpc_internal
		'cx-err:CXER1708': grpc_unavailable
		'cx-err:CXER1720': grpc_data_loss
		'cx-err:CXER1721': grpc_not_found
	}
	for code, want in cases {
		got := grpc_status_for_cxer(code)
		assert got.code == want, '${code} -> ${got.code}, want ${want}'
		assert got.message.starts_with('E_'), '${code} message ${got.message}'
	}
	// bare form parses too
	assert grpc_status_for_cxer('CXER1703').code == grpc_permission_denied
	// unmapped → UNKNOWN, never OK
	assert grpc_status_for_cxer('cx-err:CXER9999').code == grpc_unknown
	assert grpc_status_for_cxer('not-a-code').code == grpc_unknown
}

fn test_grpc_message_percent_encoding() {
	assert grpc_message_encode('plain text 1.0') == 'plain text 1.0'
	// newline (0x0A) and a non-ASCII byte get %XX-encoded; '%' escapes itself
	assert grpc_message_encode('a\nb') == 'a%0Ab'
	assert grpc_message_encode('100%') == '100%25'
}

