// store_grpc_h2_test.v — HTTP/2 frame codec (brick 3a). Pure, deterministic.

fn test_h2_frame_header_roundtrip() {
	f := H2Frame{
		typ:       h2_headers
		flags:     h2_flag_end_headers | h2_flag_end_stream
		stream_id: 5
		payload:   [u8(1), 2, 3, 4]
	}
	mut r := H2FrameReader{}
	r.feed(h2_frame_encode(f))
	got := r.next() or { panic('frame') }
	assert got.typ == h2_headers
	assert got.has_flag(h2_flag_end_headers)
	assert got.has_flag(h2_flag_end_stream)
	assert got.stream_id == 5
	assert got.payload == [u8(1), 2, 3, 4]
}

fn test_h2_reserved_bit_cleared() {
	// the high bit of the stream-id word is reserved and must be masked off.
	f := H2Frame{
		typ:       h2_data
		stream_id: 0x80000003
	}
	mut r := H2FrameReader{}
	r.feed(h2_frame_encode(f))
	got := r.next() or { panic('frame') }
	assert got.stream_id == 3, 'reserved bit must be cleared: ${got.stream_id}'
}

fn test_h2_multi_frame_and_partial() {
	mut buf := []u8{}
	buf << h2_frame_encode(H2Frame{
		typ:     h2_data
		payload: 'aa'.bytes()
	})
	buf << h2_frame_encode(H2Frame{
		typ:     h2_data
		payload: 'bbbb'.bytes()
	})
	mut r := H2FrameReader{}
	// feed in two arbitrary chunks straddling a frame boundary
	r.feed(buf[..5])
	if _ := r.next() {
		assert false, 'partial header must not yield'
	}
	r.feed(buf[5..])
	a := r.next() or { panic('a') }
	b := r.next() or { panic('b') }
	assert a.payload.bytestr() == 'aa'
	assert b.payload.bytestr() == 'bbbb'
	assert r.pending() == 0
}

fn test_h2_settings_roundtrip() {
	settings := [
		H2Setting{h2_settings_max_concurrent_streams, 128},
		H2Setting{h2_settings_initial_window_size, 1048576},
	]
	frame := h2_settings_frame(settings)
	assert frame.typ == h2_settings
	assert frame.stream_id == 0
	parsed := h2_parse_settings(frame.payload) or { panic('parse') }
	assert parsed.len == 2
	assert parsed[0].id == h2_settings_max_concurrent_streams && parsed[0].value == 128
	assert parsed[1].id == h2_settings_initial_window_size && parsed[1].value == 1048576
}

fn test_h2_settings_malformed_length() {
	if _ := h2_parse_settings([u8(0), 1, 2]) { // 3 bytes, not a multiple of 6
		assert false, 'malformed SETTINGS length must be rejected'
	}
}

fn test_h2_settings_ack() {
	ack := h2_settings_ack()
	assert ack.typ == h2_settings
	assert ack.has_flag(h2_flag_ack)
	assert ack.payload.len == 0
}

fn test_h2_control_frames() {
	wu := h2_window_update(0, 65535)
	assert wu.typ == h2_window_update && wu.payload.len == 4

	rst := h2_rst_stream(7, 0)
	assert rst.typ == h2_rst_stream && rst.stream_id == 7 && rst.payload.len == 4

	ga := h2_goaway(9, 0)
	assert ga.typ == h2_goaway && ga.payload.len == 8

	pa := h2_ping_ack('12345678'.bytes())
	assert pa.typ == h2_ping && pa.has_flag(h2_flag_ack) && pa.payload.bytestr() == '12345678'
}

fn test_h2_preface_constant() {
	// the exact RFC 7540 §3.5 client preface octets.
	assert h2_preface == 'PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n'
	assert h2_preface.len == 24
}

// ── source: vcx/platform/store_grpc_hardening_wave6_test.v ──
// store_grpc_hardening_wave6_test.v — W6 gRPC transport hardening (#222
// CONTINUATION-flood cap + SETTINGS advert, #223 RFC error emission + inbound
// limits, #224 proto3 compressed-flag reject + u64-length-before-i32-cast).

// a GOAWAY frame with the given error code present in the server output?
fn w6_goaway_code(out []u8) ?u32 {
	mut r := H2FrameReader{}
	r.feed(out)
	for {
		f := r.next() or { break }
		if f.typ == h2_goaway && f.payload.len >= 8 {
			return u32(f.payload[4]) << 24 | u32(f.payload[5]) << 16 | u32(f.payload[6]) << 8 | u32(f.payload[7])
		}
	}
	return none
}

fn w6_settings_advertises(out []u8, id u16) ?u32 {
	mut r := H2FrameReader{}
	r.feed(out)
	for {
		f := r.next() or { break }
		if f.typ == h2_settings && !f.has_flag(h2_flag_ack) {
			settings := h2_parse_settings(f.payload) or { continue }
			for s in settings {
				if s.id == id {
					return s.value
				}
			}
		}
	}
	return none
}

// ── #222: SETTINGS advertise the header-list limit; CONTINUATION flood → GOAWAY ─

fn test_settings_advertise_limits() {
	mut c := new_h2_conn()
	out := c.feed(h2_preface.bytes())
	mfs := w6_settings_advertises(out, h2_settings_max_frame_size) or {
		assert false, 'server must advertise SETTINGS_MAX_FRAME_SIZE (#223)'
		return
	}
	assert mfs == h2_max_frame_size
	mhls := w6_settings_advertises(out, h2_settings_max_header_list_size) or {
		assert false, 'server must advertise SETTINGS_MAX_HEADER_LIST_SIZE (#222)'
		return
	}
	assert mhls == h2_max_header_list_size
}

fn test_continuation_flood_goaway() {
	mut c := new_h2_conn()
	mut b := []u8{}
	b << h2_preface.bytes()
	b << h2_frame_encode(h2_settings_frame([]H2Setting{}))
	// HEADERS without END_HEADERS, then a flood of CONTINUATION frames (no
	// END_HEADERS) → must trip the CONTINUATION cap with a GOAWAY, not buffer
	// unboundedly (CVE-2024-27983 class).
	b << h2_frame_encode(H2Frame{
		typ:       h2_headers
		flags:     0 // NO end_headers
		stream_id: 1
		payload:   []u8{len: 8}
	})
	for _ in 0 .. (h2_max_continuation_frames + 5) {
		b << h2_frame_encode(H2Frame{
			typ:       h2_continuation
			flags:     0 // never END_HEADERS
			stream_id: 1
			payload:   []u8{len: 16}
		})
	}
	out := c.feed(b)
	gac := w6_goaway_code(out) or {
		assert false, 'CONTINUATION flood must emit a GOAWAY (#222)'
		return
	}
	assert gac == h2_err_enhance_your_calm, 'CONTINUATION flood → ENHANCE_YOUR_CALM, got ${gac}'
	assert c.is_fatal(), 'connection must be marked fatal after the flood'
}

// ── #223: bad preface, stream-0 HEADERS, oversized frame → RFC errors ─────────

fn test_bad_preface_goaway() {
	mut c := new_h2_conn()
	// 24 bytes that are NOT the preface
	bad := []u8{len: h2_preface.len, init: u8(0x41)}
	out := c.feed(bad)
	gac := w6_goaway_code(out) or {
		assert false, 'a non-matching preface must be a connection error (#223)'
		return
	}
	assert gac == h2_err_protocol, 'bad preface → PROTOCOL_ERROR, got ${gac}'
}

fn test_headers_on_stream_zero_goaway() {
	mut c := new_h2_conn()
	mut b := []u8{}
	b << h2_preface.bytes()
	b << h2_frame_encode(h2_settings_frame([]H2Setting{}))
	b << h2_frame_encode(H2Frame{
		typ:       h2_headers
		flags:     h2_flag_end_headers
		stream_id: 0 // illegal — HEADERS on the connection stream
		payload:   []u8{len: 4}
	})
	out := c.feed(b)
	gac := w6_goaway_code(out) or {
		assert false, 'HEADERS on stream 0 must be a connection error (#223 §5.1.1)'
		return
	}
	assert gac == h2_err_protocol, 'stream-0 HEADERS → PROTOCOL_ERROR, got ${gac}'
}

fn test_oversized_frame_goaway() {
	mut c := new_h2_conn()
	_ := c.feed(h2_preface.bytes()) // establish preface + server settings
	// a frame header declaring a length over the max frame size (payload need not
	// be present — the length is rejected before buffering).
	big := int(h2_max_frame_size) + 1
	hdr := [u8(big >> 16), u8(big >> 8), u8(big), h2_data, 0, 0, 0, 0, 1]
	out := c.feed(hdr)
	gac := w6_goaway_code(out) or {
		assert false, 'an oversized frame must be a FRAME_SIZE_ERROR (#223 §4.2)'
		return
	}
	assert gac == h2_err_frame_size, 'oversized frame → FRAME_SIZE_ERROR, got ${gac}'
}

// ── #224: proto length truncation guard + compressed-flag reject ──────────────

fn test_proto_length_truncation_guard() {
	// a length-delimited field whose varint length is > pb_max_len_delim must be
	// rejected (not int()-truncated → wrong read). Field 1 (store), wire type 2,
	// then a huge varint length.
	mut b := []u8{}
	b << u8(0x0a) // field 1, wire type 2 (len-delim)
	// varint for 2^40 (way over the 64 MiB cap, and > i32) — 6 bytes
	pb_write_varint(mut b, u64(1) << 40)
	b << [u8(1), 2, 3] // a few bytes (far fewer than declared)
	r := pb_decode_put_request(b)
	assert r == none, 'a >cap length-delimited field must be rejected (#224), not truncated'
}

fn test_grpc_compressed_message_rejected() {
	// an LPM with the compressed flag set → the reader flags it; dispatch must
	// reject with UNIMPLEMENTED, never read the (compressed) bytes as identity.
	mut fr := GrpcFrameReader{}
	mut lpm := []u8{}
	lpm << u8(1) // compressed flag = 1
	lpm << [u8(0), 0, 0, 3] // length 3
	lpm << [u8(0x0a), 0x01, `x`]
	fr.feed(lpm)
	f := fr.next() or {
		assert false, 'frame must parse'
		return
	}
	assert f.compressed, 'the compressed flag must be surfaced (#224)'
}

// ── source: vcx/platform/store_grpc_hpack_test.v ──
// store_grpc_hpack_test.v — HPACK core (brick 3b): integer + literal string +
// dynamic table + RFC 7541 Appendix C (literal) examples. Huffman is the next
// sub-brick; here we assert it fails honestly rather than guessing.

fn b(bytes ...u8) []u8 {
	return bytes
}

fn test_hpack_integer_roundtrip() {
	for prefix in [5, 7] {
		for v in [0, 1, 10, 30, 31, 127, 128, 1337, 100000] {
			mut out := []u8{}
			hpack_encode_integer(mut out, v, prefix, 0)
			got, p := hpack_decode_integer(out, 0, prefix) or { panic('decode ${v}/${prefix}') }
			assert got == v, 'int ${v} prefix ${prefix} -> ${got}'
			assert p == out.len
		}
	}
}

// RFC 7541 C.2.4 — Indexed Header Field (:method GET = static index 2 → 0x82).
fn test_hpack_indexed_static() {
	mut d := new_hpack_decoder(4096)
	hs := d.decode(b(0x82)) or { panic('decode') }
	assert hs.len == 1
	assert hs[0].name == ':method' && hs[0].value == 'GET'
}

// RFC 7541 C.2.2 — Literal without Indexing (:path /sample/path).
fn test_hpack_literal_without_indexing() {
	mut block := [u8(0x04), 0x0c] // 0x04 = literal w/o indexing, name index 4 (:path)
	block << '/sample/path'.bytes() // 12 bytes = 0x0c
	mut d := new_hpack_decoder(4096)
	hs := d.decode(block) or { panic('decode') }
	assert hs.len == 1
	assert hs[0].name == ':path' && hs[0].value == '/sample/path'
	assert d.dyn.len == 0, 'literal-without-indexing must not touch the dynamic table'
}

// RFC 7541 C.2.1 — Literal with Incremental Indexing, new name (custom-key:
// custom-header) → also inserted into the dynamic table.
fn test_hpack_literal_incremental_new_name() {
	mut block := [u8(0x40), 0x0a] // literal w/ incremental indexing, name index 0
	block << 'custom-key'.bytes() // 10
	block << u8(0x0d)
	block << 'custom-header'.bytes() // 13
	mut d := new_hpack_decoder(4096)
	hs := d.decode(block) or { panic('decode') }
	assert hs.len == 1
	assert hs[0].name == 'custom-key' && hs[0].value == 'custom-header'
	assert d.dyn.len == 1, 'incremental indexing must insert into the dynamic table'
	// the new entry is now addressable at index 62 (most recent)
	got := d.at(62) or { panic('dyn at 62') }
	assert got.name == 'custom-key' && got.value == 'custom-header'
}

// RFC 7541 C.3.1 — a full (literal, non-Huffman) request header set.
fn test_hpack_full_request_c31() {
	mut block := [u8(0x82), 0x86, 0x84, 0x41, 0x0f] // GET, http, /, :authority(idx1)+literal
	block << 'www.example.com'.bytes() // 15 = 0x0f
	mut d := new_hpack_decoder(4096)
	hs := d.decode(block) or { panic('decode') }
	assert hs.len == 4
	assert hs[0].name == ':method' && hs[0].value == 'GET'
	assert hs[1].name == ':scheme' && hs[1].value == 'http'
	assert hs[2].name == ':path' && hs[2].value == '/'
	assert hs[3].name == ':authority' && hs[3].value == 'www.example.com'
}

fn test_hpack_dynamic_table_eviction() {
	// max_size too small to hold two ~ (10+13+32)=55-byte entries → eviction.
	mut d := new_hpack_decoder(60)
	mut blk1 := [u8(0x40), 0x0a]
	blk1 << 'custom-key'.bytes()
	blk1 << u8(0x0d)
	blk1 << 'custom-header'.bytes()
	d.decode(blk1) or { panic('1') }
	assert d.dyn.len == 1
	// insert a second entry → the first is evicted (table holds only one ~55B entry)
	mut blk2 := [u8(0x40), 0x09]
	blk2 << 'other-key'.bytes() // 9
	blk2 << u8(0x05)
	blk2 << 'other'.bytes() // 5
	d.decode(blk2) or { panic('2') }
	assert d.dyn.len == 1, 'older entry must be evicted; dyn=${d.dyn.len}'
	assert (d.at(62) or { panic('x') }).name == 'other-key'
}

fn test_hpack_encode_roundtrip() {
	headers := [
		HpackHeader{':status', '200'},
		HpackHeader{'content-type', 'application/grpc'},
		HpackHeader{'grpc-status', '0'},
	]
	mut d := new_hpack_decoder(4096)
	got := d.decode(hpack_encode_header_list(headers)) or { panic('decode') }
	assert got.len == 3
	assert got[0].name == ':status' && got[0].value == '200'
	assert got[1].name == 'content-type' && got[1].value == 'application/grpc'
	assert got[2].name == 'grpc-status' && got[2].value == '0'
}

fn test_hpack_huffman_value_decodes() {
	// RFC 7541 C.4.1: literal w/ incremental indexing, name index 1 (:authority),
	// Huffman-coded value (0x8c = H-bit + len 12) "www.example.com".
	mut block := [u8(0x41), 0x8c, 0xf1, 0xe3, 0xc2, 0xe5, 0xf2, 0x3a, 0x6b, 0xa0, 0xab, 0x90,
		0xf4, 0xff]
	mut d := new_hpack_decoder(4096)
	hs := d.decode(block) or { panic('decode huffman header: ${err}') }
	assert hs.len == 1
	assert hs[0].name == ':authority'
	assert hs[0].value == 'www.example.com'
}

// ── source: vcx/platform/store_grpc_huffman_test.v ──
// store_grpc_huffman_test.v — HPACK Huffman decode (brick 3b-huffman) validated
// against the RFC 7541 Appendix C.4/C.6 examples (canonical byte sequences →
// exact strings) plus a structural prefix-free / completeness check of the trie.

fn hb(bytes ...u8) []u8 {
	return bytes
}

// The trie must be a complete, prefix-free code: exactly 256 leaves, and no
// symbol node also has children (no code is a prefix of another). This catches
// any table transcription collision regardless of the example coverage.
fn huff_first_descendant_sym(nodes []HuffNode, start int) int {
	mut stack := [start]
	for stack.len > 0 {
		i := stack.pop()
		for b in 0 .. 2 {
			c := nodes[i].child[b]
			if c != -1 {
				if nodes[c].sym >= 0 {
					return nodes[c].sym
				}
				stack << c
			}
		}
	}
	return -1
}

fn test_huffman_trie_prefix_free_and_complete() {
	t := hpack_huff_trie()
	mut leaves := 0
	for idx, n in t.nodes {
		if n.sym >= 0 {
			leaves++
			if n.child[0] != -1 || n.child[1] != -1 {
				desc := huff_first_descendant_sym(t.nodes, idx)
				assert false, 'sym ${n.sym} (code 0x${hpack_huff_code[n.sym].hex()}/${hpack_huff_nbits[n.sym]}) is a prefix of sym ${desc} (code 0x${hpack_huff_code[desc].hex()}/${hpack_huff_nbits[desc]})'
			}
		}
	}
	assert leaves == 256, 'expected 256 symbols, got ${leaves}'
}

fn test_huffman_rfc_c4_examples() {
	// C.4.1 — "www.example.com"
	assert hpack_huffman_decode(hb(0xf1, 0xe3, 0xc2, 0xe5, 0xf2, 0x3a, 0x6b, 0xa0, 0xab, 0x90,
		0xf4, 0xff))? == 'www.example.com'
	// C.4.2 — "no-cache"
	assert hpack_huffman_decode(hb(0xa8, 0xeb, 0x10, 0x64, 0x9c, 0xbf))? == 'no-cache'
	// C.4.3 — "custom-key" / "custom-value"
	assert hpack_huffman_decode(hb(0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xa9, 0x7d, 0x7f))? == 'custom-key'
	assert hpack_huffman_decode(hb(0x25, 0xa8, 0x49, 0xe9, 0x5b, 0xb8, 0xe8, 0xb4, 0xbf))? == 'custom-value'
}

fn test_huffman_rfc_c6_examples() {
	// C.6.1 response field values
	assert hpack_huffman_decode(hb(0x64, 0x02))? == '302'
	assert hpack_huffman_decode(hb(0xae, 0xc3, 0x77, 0x1a, 0x4b))? == 'private'
	assert hpack_huffman_decode(hb(0x9d, 0x29, 0xad, 0x17, 0x18, 0x63, 0xc7, 0x8f, 0x0b, 0x97,
		0xc8, 0xe9, 0xae, 0x82, 0xae, 0x43, 0xd3))? == 'https://www.example.com'
	// the C.6.1 date value
	assert hpack_huffman_decode(hb(0xd0, 0x7a, 0xbe, 0x94, 0x10, 0x54, 0xd4, 0x44, 0xa8, 0x20,
		0x05, 0x95, 0x04, 0x0b, 0x81, 0x66, 0xe0, 0x82, 0xa6, 0x2d, 0x1b, 0xff))? == 'Mon, 21 Oct 2013 20:13:21 GMT'
}

fn test_huffman_empty() {
	assert hpack_huffman_decode([]u8{})? == ''
}

fn test_huffman_invalid_padding_errors() {
	// all-zero bytes are not valid EOS padding (padding must be 1-bits) → error.
	if _ := hpack_huffman_decode(hb(0x00)) {
		assert false, 'zero padding must not decode'
	}
	// a full byte of 1s is >7 bits of padding → error.
	if _ := hpack_huffman_decode(hb(0xff, 0xff, 0xff, 0xff)) {
		assert false, 'over-long all-ones (EOS-ish) must not decode'
	}
}

